  assert isinstance(e,ValueError)
  assert e.to_dict()=={'error':'invalid_config','issues':[{'path':path,'code':code}]}
 else: raise AssertionError('invalid accepted')

import json
from configkit import Config, loads, dumps
v1={'name':'demo','host':'localhost','port':8080,'enabled':False}
v2={'version':2,'service':{'name':'demo','endpoint':{'host':'localhost','port':8080}},'enabled':False}
from configkit.config.errors import ConfigError
for field,value,path in [('name',' ','service.name'),('host',None,'service.endpoint.host'),('port',True,'service.endpoint.port'),('port',65536,'service.endpoint.port'),('enabled',1,'enabled')]:
 d=json.loads(json.dumps(v2));target=d if field=='enabled' else d['service'] if field=='name' else d['service']['endpoint'];target[field]=value
 try: loads(json.dumps(d))
 except ConfigError as e: assert e.to_dict()=={'error':'invalid_config','issues':[{'path':path,'code':'invalid'}]}
 else: raise AssertionError('invalid accepted')

